def get_cards(resp):
    if not isinstance(resp, dict):
        return []
    for top in ("data","data_preview"):
        block=resp.get(top)
        if isinstance(block, dict):
            arr=block.get("details") or block.get("cards")
            if isinstance(arr, list):
                return arr
    return []
