def flatten_cards(obj):
    out=[]
    for r in (obj.get("results") or []):
        resp=r.get("response") or {}
        d=(resp.get("data") or resp.get("data_preview") or {})
        out.extend((d.get("details") or d.get("cards") or []))
    return out
